        bool reverted;
        try c.transferAnyERC20Token(tokenAddress, tokenOwner, tokens) {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted || c.currentBetLimit() == c.currentBetLimit());
    }

